public static int countDivisors(int n) {
    int count = 0;
    for (int i = 1; i <= n; i++) {
        if (n % i == 0) {
            count++;
        }
    }
    return count;
}

public static boolean isPrime(int n) {
    // ראשוני — בדיוק שני מחלקים: 1 והמספר עצמו
    return countDivisors(n) == 2;
}
